python3 << 'PYEOF'
import json

with open('/tmp/analysis_results.json') as f:
    R = json.load(f)

kpis = R['kpis']
pd_dist = R['profit_distribution']
model_stats = R['model_stats']
colorway_stats = R['colorway_stats']
top_combos = R['top_combos']
bottom_combos = R['bottom_combos']
condition_stats = R['condition_stats']
condition_model = R['condition_model']
channel_stats = R['channel_stats']
channel_condition = R['channel_condition']
monthly_trends = R['monthly_trends']
yearly_stats = R['yearly_stats']
monthly_seasonality = R['monthly_seasonality']
quarter_stats = R['quarter_stats']
profit_hist = R['profit_histogram']

# Helper functions
def fmt_usd(v):
    if v >= 0:
        return f"${v:,.2f}"
    return f"-${abs(v):,.2f}"

def fmt_pct(v):
    return f"{v:.1f}%"

# ---- BUILD HTML ----

# Model table rows
model_rows = ""
for m in model_stats:
    profit_class = "positive" if m['avg_profit'] >= 0 else "negative"
    model_rows += f"""<tr>
        <td class="model-name">{m['Shoe_Model']}</td>
        <td>{m['count']:,}</td>
        <td>{fmt_usd(m['avg_retail'])}</td>
        <td>{fmt_usd(m['avg_resale'])}</td>
        <td class="{profit_class}">{fmt_usd(m['avg_profit'])}</td>
        <td>{m['avg_days']:.0f}</td>
        <td>{fmt_pct(m['pct_profitable'])}</td>
    </tr>"""

# Colorway table rows
cw_rows = ""
for c in colorway_stats:
    profit_class = "positive" if c['avg_profit'] >= 0 else "negative"
    cw_rows += f"""<tr>
        <td class="model-name">{c['Colorway']}</td>
        <td>{c['count']:,}</td>
        <td>{fmt_usd(c['avg_retail'])}</td>
        <td>{fmt_usd(c['avg_resale'])}</td>
        <td class="{profit_class}">{fmt_usd(c['avg_profit'])}</td>
        <td>{c['avg_days']:.0f}</td>
        <td>{fmt_pct(c['pct_profitable'])}</td>
    </tr>"""

# Top combos rows
combo_rows = ""
for i, c in enumerate(top_combos):
    combo_rows += f"""<tr>
        <td>{i+1}</td>
        <td class="model-name">{c['Shoe_Model']}</td>
        <td>{c['Colorway']}</td>
        <td>{c['count']:,}</td>
        <td class="positive">{fmt_usd(c['avg_profit'])}</td>
        <td>{c['avg_days']:.0f}</td>
        <td>{fmt_pct(c['pct_profitable'])}</td>
    </tr>"""

# Bottom combos rows
bottom_rows = ""
for i, c in enumerate(bottom_combos):
    bottom_rows += f"""<tr>
        <td>{i+1}</td>
        <td class="model-name">{c['Shoe_Model']}</td>
        <td>{c['Colorway']}</td>
        <td>{c['count']:,}</td>
        <td class="negative">{fmt_usd(c['avg_profit'])}</td>
        <td>{c['avg_days']:.0f}</td>
        <td>{fmt_pct(c['pct_profitable'])}</td>
    </tr>"""

# Condition table rows
cond_rows = ""
cond_order = ['Deadstock (Brand New)', 'VNDS (Very Near Deadstock)', 'Used']
for cname in cond_order:
    c = next(x for x in condition_stats if x['Condition'] == cname)
    profit_class = "positive" if c['avg_profit'] >= 0 else "negative"
    cond_rows += f"""<tr>
        <td class="model-name">{c['Condition']}</td>
        <td>{c['count']:,}</td>
        <td>{fmt_usd(c['avg_retail'])}</td>
        <td>{fmt_usd(c['avg_resale'])}</td>
        <td class="{profit_class}">{fmt_usd(c['avg_profit'])}</td>
        <td>{c['avg_ratio']:.3f}x</td>
        <td>{c['avg_days']:.0f}</td>
        <td>{fmt_pct(c['pct_profitable'])}</td>
    </tr>"""

# Channel table rows
ch_rows = ""
for c in channel_stats:
    profit_class = "positive" if c['avg_profit'] >= 0 else "negative"
    ch_rows += f"""<tr>
        <td class="model-name">{c['Sales_Channel']}</td>
        <td>{c['count']:,}</td>
        <td>{fmt_usd(c['avg_resale'])}</td>
        <td class="{profit_class}">{fmt_usd(c['avg_profit'])}</td>
        <td>{c['avg_days']:.1f}</td>
        <td>{c['median_days']:.0f}</td>
        <td>{c['avg_ratio']:.3f}x</td>
        <td>{fmt_pct(c['pct_profitable'])}</td>
    </tr>"""

# Yearly stats rows
yr_rows = ""
for y in yearly_stats:
    profit_class = "positive" if y['avg_profit'] >= 0 else "negative"
    yr_rows += f"""<tr>
        <td>{y['Year']}</td>
        <td>{y['count']:,}</td>
        <td>{fmt_usd(y['avg_resale'])}</td>
        <td class="{profit_class}">{fmt_usd(y['avg_profit'])}</td>
        <td>{y['avg_days']:.1f}</td>
        <td>{fmt_pct(y['pct_profitable'])}</td>
        <td>{fmt_usd(y['total_profit'])}</td>
    </tr>"""

# Quarter stats rows
qtr_rows = ""
for q in quarter_stats:
    profit_class = "positive" if q['avg_profit'] >= 0 else "negative"
    qtr_rows += f"""<tr>
        <td>Q{q['Quarter']}</td>
        <td>{q['count']:,}</td>
        <td class="{profit_class}">{fmt_usd(q['avg_profit'])}</td>
        <td>{q['avg_days']:.1f}</td>
        <td>{fmt_pct(q['pct_profitable'])}</td>
    </tr>"""

# Chart data
monthly_labels = json.dumps([m['YearMonth'] for m in monthly_trends])
monthly_avg_profit = json.dumps([m['avg_profit'] for m in monthly_trends])
monthly_avg_resale = json.dumps([m['avg_resale'] for m in monthly_trends])
monthly_counts = json.dumps([m['count'] for m in monthly_trends])
monthly_pct_prof = json.dumps([m['pct_profitable'] for m in monthly_trends])

season_labels = json.dumps(['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'])
season_profit = json.dumps([m['avg_profit'] for m in monthly_seasonality])
season_resale = json.dumps([m['avg_resale'] for m in monthly_seasonality])
season_count = json.dumps([m['count'] for m in monthly_seasonality])

hist_labels = json.dumps(profit_hist['labels'])
hist_values = json.dumps(profit_hist['values'])

model_names = json.dumps([m['Shoe_Model'].replace('Air Jordan ', 'AJ') for m in model_stats])
model_profits = json.dumps([m['avg_profit'] for m in model_stats])
model_days = json.dumps([m['avg_days'] for m in model_stats])

cw_names = json.dumps([c['Colorway'] for c in colorway_stats])
cw_profits = json.dumps([c['avg_profit'] for c in colorway_stats])

cond_names_chart = json.dumps([c['Condition'].split(' (')[0] for c in condition_stats if c['Condition'] in cond_order])
cond_profits_chart = json.dumps([next(x for x in condition_stats if x['Condition'] == cn)['avg_profit'] for cn in cond_order])
cond_resale_chart = json.dumps([next(x for x in condition_stats if x['Condition'] == cn)['avg_resale'] for cn in cond_order])
cond_pct_chart = json.dumps([next(x for x in condition_stats if x['Condition'] == cn)['pct_profitable'] for cn in cond_order])
cond_days_chart = json.dumps([next(x for x in condition_stats if x['Condition'] == cn)['avg_days'] for cn in cond_order])

ch_names = json.dumps([c['Sales_Channel'] for c in channel_stats])
ch_profits = json.dumps([c['avg_profit'] for c in channel_stats])
ch_days = json.dumps([c['avg_days'] for c in channel_stats])
ch_counts = json.dumps([c['count'] for c in channel_stats])
ch_pct = json.dumps([c['pct_profitable'] for c in channel_stats])

# Build condition-model heatmap data
models_list = sorted(set(r['Shoe_Model'] for r in condition_model))
conds_list = cond_order
heatmap_data = []
for ci, cond in enumerate(conds_list):
    for mi, model in enumerate(models_list):
        match = [r for r in condition_model if r['Condition'] == cond and r['Shoe_Model'] == model]
        val = match[0]['avg_profit'] if match else 0
        heatmap_data.append({'x': mi, 'y': ci, 'v': val})

heatmap_models_json = json.dumps([m.replace('Air Jordan ', 'AJ') for m in models_list])
heatmap_conds_json = json.dumps(['Deadstock', 'VNDS', 'Used'])
heatmap_data_json = json.dumps(heatmap_data)

# Channel-condition cross data for stacked bar
ch_cond_data = {}
for r in channel_condition:
    ch = r['Sales_Channel']
    if ch not in ch_cond_data:
        ch_cond_data[ch] = {}
    ch_cond_data[ch][r['Condition']] = r['avg_profit']

ch_cond_channels = [c['Sales_Channel'] for c in channel_stats]
ch_cond_ds = json.dumps([ch_cond_data.get(ch, {}).get('Deadstock (Brand New)', 0) for ch in ch_cond_channels])
ch_cond_vnds = json.dumps([ch_cond_data.get(ch, {}).get('VNDS (Very Near Deadstock)', 0) for ch in ch_cond_channels])
ch_cond_used = json.dumps([ch_cond_data.get(ch, {}).get('Used', 0) for ch in ch_cond_channels])
ch_cond_labels = json.dumps(ch_cond_channels)

# Deadstock premium info
ds_data = next(x for x in condition_stats if x['Condition'] == 'Deadstock (Brand New)')
vnds_data = next(x for x in condition_stats if x['Condition'] == 'VNDS (Very Near Deadstock)')
used_data = next(x for x in condition_stats if x['Condition'] == 'Used')

ds_premium_over_vnds = round(ds_data['avg_resale'] - vnds_data['avg_resale'], 2)
ds_premium_over_used = round(ds_data['avg_resale'] - used_data['avg_resale'], 2)
vnds_premium_over_used = round(vnds_data['avg_resale'] - used_data['avg_resale'], 2)

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Air Jordan Sneaker Resale Market Analysis (2023–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.4/dist/chart.umd.min.js"></script>
<style>
:root {{
    --primary: #1a1a2e;
    --secondary: #16213e;
    --accent: #e94560;
    --accent2: #0f3460;
    --bg: #f8f9fa;
    --card-bg: #ffffff;
    --text: #2c3e50;
    --text-light: #6c757d;
