.premium-badge.low {{ background: #f8d7da; color: #721c24; }}
@media (max-width: 1024px) {{
    .kpi-strip {{ grid-template-columns: repeat(3, 1fr); }}
    .grid-2, .grid-3 {{ grid-template-columns: 1fr; }}
}}
@media (max-width: 768px) {{
    .kpi-strip {{ grid-template-columns: repeat(2, 1fr); }}
    .header h1 {{ font-size: 1.6rem; }}
}}
</style>
</head>
<body>

<div class="header">
    <div class="container">
        <h1>Air Jordan Sneaker Resale Market Analysis</h1>
        <div class="subtitle">A comprehensive analysis of {kpis['total_transactions']:,} secondary-market transactions examining pricing dynamics, profit margins, inventory velocity, and channel performance across models, colorways, and conditions.</div>
        <div class="meta">Data Period: {kpis['date_range']} &nbsp;&bull;&nbsp; Transactions: {kpis['total_transactions']:,} &nbsp;&bull;&nbsp; Generated: April 2026</div>
    </div>
</div>

<!-- KPI Strip -->
<div class="container">
<div class="kpi-strip">
    <div class="kpi-card">
        <div class="kpi-value">{fmt_usd(kpis['avg_profit_margin'])}</div>
        <div class="kpi-label">Avg Profit Margin</div>
        <div class="kpi-detail">Median: {fmt_usd(kpis['median_profit_margin'])}</div>
    </div>
    <div class="kpi-card">
        <div class="kpi-value">{kpis['resale_premium_rate']}%</div>
        <div class="kpi-label">Resale Premium Rate</div>
        <div class="kpi-detail">{int(kpis['resale_premium_rate']*50)}+ of 5,000 sold above retail</div>
    </div>
    <div class="kpi-card">
        <div class="kpi-value">{kpis['avg_days_inventory']:.0f} days</div>
        <div class="kpi-label">Avg Days in Inventory</div>
        <div class="kpi-detail">Median: {kpis['median_days_inventory']:.0f} days</div>
    </div>
    <div class="kpi-card">
        <div class="kpi-value">{kpis['avg_resale_to_retail']:.2f}x</div>
        <div class="kpi-label">Resale-to-Retail Ratio</div>
        <div class="kpi-detail">Avg resale: {fmt_usd(kpis['avg_resale'])}</div>
    </div>
    <div class="kpi-card">
        <div class="kpi-value">{fmt_usd(kpis['top_colorway_margin'])}</div>
        <div class="kpi-label">Top Colorway Margin</div>
        <div class="kpi-detail">{kpis['top_colorway']}</div>
    </div>
</div>
</div>

<div class="container">

<!-- Section 1: Market Overview -->
<div class="section">
    <div class="section-header">
        <div class="section-number">1</div>
        <h2>Market Overview & Transaction Summary</h2>
    </div>

    <div class="stat-grid">
        <div class="stat-item">
            <div class="stat-val">{kpis['total_transactions']:,}</div>
            <div class="stat-lbl">Total Transactions</div>
        </div>
        <div class="stat-item">
            <div class="stat-val">{fmt_usd(kpis['avg_retail'])}</div>
            <div class="stat-lbl">Avg Retail Price</div>
        </div>
        <div class="stat-item">
            <div class="stat-val">{fmt_usd(kpis['avg_resale'])}</div>
            <div class="stat-lbl">Avg Resale Price</div>
        </div>
        <div class="stat-item">
            <div class="stat-val">{fmt_usd(kpis['total_profit'])}</div>
            <div class="stat-lbl">Total Market Profit</div>
        </div>
        <div class="stat-item">
            <div class="stat-val">{fmt_pct(pd_dist['pct_profit'])}</div>
            <div class="stat-lbl">Profitable Trades</div>
        </div>
        <div class="stat-item">
            <div class="stat-val">{fmt_pct(pd_dist['pct_loss'])}</div>
            <div class="stat-lbl">Loss-Making Trades</div>
        </div>
    </div>

    <div class="grid-2">
        <div class="card">
            <h3>Profit Margin Distribution</h3>
            <div class="chart-container">
                <canvas id="profitHistChart"></canvas>
            </div>
        </div>
        <div class="card">
            <h3>Distribution Statistics</h3>
            <table>
                <tr><td>Minimum</td><td class="negative">{fmt_usd(pd_dist['min'])}</td></tr>
                <tr><td>25th Percentile (Q1)</td><td>{fmt_usd(pd_dist['q1'])}</td></tr>
                <tr><td>Median (Q2)</td><td>{fmt_usd(pd_dist['median'])}</td></tr>
                <tr><td>75th Percentile (Q3)</td><td>{fmt_usd(pd_dist['q3'])}</td></tr>
                <tr><td>Maximum</td><td class="positive">{fmt_usd(pd_dist['max'])}</td></tr>
                <tr><td>Standard Deviation</td><td>{fmt_usd(pd_dist['std'])}</td></tr>
                <tr><td>Interquartile Range</td><td>{fmt_usd(pd_dist['q3'] - pd_dist['q1'])}</td></tr>
            </table>
            <div class="insight-box" style="margin-top:16px;">
                <strong>Key Insight:</strong> The median profit ({fmt_usd(pd_dist['median'])}) is significantly lower than the mean ({fmt_usd(kpis['avg_profit_margin'])}), indicating the distribution is right-skewed — a minority of high-margin Deadstock transactions pull the average up while a large portion of trades are near break-even or negative.
            </div>
        </div>
    </div>
</div>

<!-- Section 2: Model & Colorway Analysis -->
<div class="section">
    <div class="section-header">
        <div class="section-number">2</div>
        <h2>Performance by Shoe Model & Colorway</h2>
    </div>

    <div class="card">
        <h3>Performance by Air Jordan Model</h3>
        <table>
            <thead>
                <tr>
                    <th>Model</th>
                    <th>Txns</th>
                    <th>Avg Retail</th>
                    <th>Avg Resale</th>
                    <th>Avg Profit</th>
                    <th>Avg Days</th>
                    <th>% Profitable</th>
                </tr>
            </thead>
            <tbody>{model_rows}</tbody>
        </table>
    </div>

    <div class="grid-2">
        <div class="card">
            <h3>Average Profit by Model</h3>
            <div class="chart-container">
                <canvas id="modelProfitChart"></canvas>
            </div>
        </div>
        <div class="card">
            <h3>Average Profit by Colorway</h3>
            <div class="chart-container">
                <canvas id="colorwayProfitChart"></canvas>
            </div>
        </div>
    </div>

    <div class="card">
        <h3>Performance by Colorway</h3>
        <table>
            <thead>
                <tr>
                    <th>Colorway</th>
                    <th>Txns</th>
                    <th>Avg Retail</th>
                    <th>Avg Resale</th>
                    <th>Avg Profit</th>
                    <th>Avg Days</th>
                    <th>% Profitable</th>
                </tr>
            </thead>
            <tbody>{cw_rows}</tbody>
        </table>
    </div>

    <div class="grid-2">
        <div class="card">
            <h3>Top 15 Model-Colorway Combinations (by Avg Profit)</h3>
            <table>
                <thead><tr><th>#</th><th>Model</th><th>Colorway</th><th>Txns</th><th>Avg Profit</th><th>Avg Days</th><th>% Prof.</th></tr></thead>
                <tbody>{combo_rows}</tbody>
            </table>
        </div>
        <div class="card">
            <h3>Bottom 10 Model-Colorway Combinations (Worst Margins)</h3>
            <table>
                <thead><tr><th>#</th><th>Model</th><th>Colorway</th><th>Txns</th><th>Avg Profit</th><th>Avg Days</th><th>% Prof.</th></tr></thead>
                <tbody>{bottom_rows}</tbody>
            </table>
            <div class="insight-box" style="margin-top:16px;">
                <strong>Sourcing Warning:</strong> The bottom performers are dominated by Used-condition shoes and lower-demand colorways. These combinations frequently sell below retail, making them unprofitable sourcing targets regardless of channel.
            </div>
        </div>
    </div>
</div>

<!-- Section 3: Condition Impact -->
<div class="section">
    <div class="section-header">
        <div class="section-number">3</div>
        <h2>Impact of Shoe Condition on Resale Value</h2>
    </div>

    <div class="card">
        <h3>Condition Tier Comparison</h3>
        <table>
            <thead>
                <tr>
                    <th>Condition</th>
                    <th>Txns</th>
                    <th>Avg Retail</th>
                    <th>Avg Resale</th>
                    <th>Avg Profit</th>
                    <th>Resale/Retail</th>
                    <th>Avg Days</th>
                    <th>% Profitable</th>
                </tr>
            </thead>
            <tbody>{cond_rows}</tbody>
        </table>
    </div>

    <div class="stat-grid">
        <div class="stat-item">
            <div class="stat-val" style="color:var(--green);">+{fmt_usd(ds_premium_over_used)}</div>
            <div class="stat-lbl">Deadstock Premium vs Used</div>
        </div>
        <div class="stat-item">
            <div class="stat-val" style="color:var(--green);">+{fmt_usd(ds_premium_over_vnds)}</div>
            <div class="stat-lbl">Deadstock Premium vs VNDS</div>
        </div>
        <div class="stat-item">
            <div class="stat-val" style="color:var(--blue);">+{fmt_usd(vnds_premium_over_used)}</div>
            <div class="stat-lbl">VNDS Premium vs Used</div>
        </div>
    </div>

    <div class="grid-2">
        <div class="card">
            <h3>Average Resale Price & Profit by Condition</h3>
            <div class="chart-container">
                <canvas id="conditionChart"></canvas>
            </div>
        </div>
        <div class="card">
            <h3>Profitability Rate & Inventory Days by Condition</h3>
            <div class="chart-container">
                <canvas id="conditionMetricsChart"></canvas>
            </div>
        </div>
    </div>

    <div class="card">
        <h3>Condition × Model Heatmap: Average Profit Margin (USD)</h3>
        <div class="chart-container">
            <canvas id="heatmapChart"></canvas>
        </div>
    </div>

    <div class="insight-box">
        <strong>Condition Premium Analysis:</strong> Deadstock items command an average resale premium of {fmt_usd(ds_premium_over_used)} over Used pairs and {fmt_usd(ds_premium_over_vnds)} over VNDS. Critically, {fmt_pct(ds_data['pct_profitable'])} of Deadstock transactions are profitable vs. only {fmt_pct(used_data['pct_profitable'])} of Used — a {ds_data['pct_profitable'] - used_data['pct_profitable']:.1f} percentage-point gap that makes condition the single most predictive variable for profitability.
    </div>
</div>

<!-- Section 4: Channel Performance -->
<div class="section">
    <div class="section-header">
        <div class="section-number">4</div>
        <h2>Sales Channel Performance & Inventory Velocity</h2>
    </div>

    <div class="card">
        <h3>Channel Comparison</h3>
        <table>
            <thead>
                <tr>
                    <th>Channel</th>
                    <th>Txns</th>
                    <th>Avg Resale</th>
                    <th>Avg Profit</th>
                    <th>Avg Days</th>
                    <th>Median Days</th>
                    <th>Resale/Retail</th>
                    <th>% Profitable</th>
                </tr>
            </thead>
            <tbody>{ch_rows}</tbody>
        </table>
    </div>

    <div class="grid-2">
        <div class="card">
            <h3>Profit Margin vs Inventory Velocity by Channel</h3>
            <div class="chart-container">
                <canvas id="channelScatterChart"></canvas>
            </div>
        </div>
        <div class="card">
            <h3>Profitability Rate by Channel</h3>
            <div class="chart-container">
                <canvas id="channelPctChart"></canvas>
            </div>
        </div>
    </div>

    <div class="card">
        <h3>Average Profit by Channel × Condition</h3>
        <div class="chart-container">
            <canvas id="channelCondChart"></canvas>
        </div>
    </div>

    <div class="insight-box">
        <strong>Margin vs. Velocity Trade-off:</strong> The core strategic tension for resellers: channels with higher average margins may exhibit slower inventory turnover. Identify whether it is more profitable to sell quickly at a moderate margin or hold for a premium price. The scatter plot above maps this relationship — channels in the upper-left quadrant (high margin, low days) are optimal.
    </div>
</div>

<!-- Section 5: Temporal Trends -->
<div class="section">
    <div class="section-header">
        <div class="section-number">5</div>
        <h2>Temporal Trends & Seasonality</h2>
    </div>

    <div class="card">
        <h3>Yearly Performance Summary</h3>
        <table>
            <thead>
                <tr>
                    <th>Year</th>
                    <th>Txns</th>
                    <th>Avg Resale</th>
                    <th>Avg Profit</th>
                    <th>Avg Days</th>
                    <th>% Profitable</th>
                    <th>Total Profit</th>
                </tr>
            </thead>
            <tbody>{yr_rows}</tbody>
        </table>
    </div>

    <div class="card">
        <h3>Monthly Average Profit Margin Trend</h3>
        <div class="chart-container-tall">
            <canvas id="monthlyProfitChart"></canvas>
        </div>
    </div>

    <div class="grid-2">
        <div class="card">
            <h3>Monthly Transaction Volume</h3>
            <div class="chart-container">
                <canvas id="monthlyVolumeChart"></canvas>
            </div>
        </div>
        <div class="card">
            <h3>Monthly Profitability Rate</h3>
            <div class="chart-container">
                <canvas id="monthlyPctChart"></canvas>
            </div>
        </div>
    </div>

    <div class="grid-2">
        <div class="card">
            <h3>Seasonal Patterns (Average by Calendar Month)</h3>
            <div class="chart-container">
                <canvas id="seasonChart"></canvas>
            </div>
        </div>
        <div class="card">
            <h3>Quarterly Performance Summary</h3>
            <table>
                <thead><tr><th>Quarter</th><th>Txns</th><th>Avg Profit</th><th>Avg Days</th><th>% Profitable</th></tr></thead>
                <tbody>{qtr_rows}</tbody>
            </table>
            <div class="insight-box" style="margin-top:16px;">
                <strong>Seasonality:</strong> Examine quarterly and monthly patterns to identify optimal buying and selling windows. Resellers should monitor whether holiday seasons, back-to-school periods, or new release cycles create predictable margin fluctuations.
            </div>
        </div>
    </div>
</div>

<!-- Section 6: Strategic Recommendations -->
<div class="section">
    <div class="section-header">
        <div class="section-number">6</div>
        <h2>Key Findings & Strategic Recommendations</h2>
    </div>

    <div class="card">
        <h3>Key Findings</h3>
        <ul class="rec-list">
            <li>
                <strong>Condition is the dominant profit driver.</strong>
                Deadstock items average {fmt_usd(ds_data['avg_profit'])} profit with a {fmt_pct(ds_data['pct_profitable'])} profitability rate, while Used items average {fmt_usd(used_data['avg_profit'])} with only {fmt_pct(used_data['pct_profitable'])} profitable. VNDS sits between at {fmt_usd(vnds_data['avg_profit'])} avg profit and {fmt_pct(vnds_data['pct_profitable'])} profitability.
            </li>
            <li>
                <strong>Premium colorways outperform regardless of model.</strong>
                {kpis['top_colorway']} leads all colorways with an average margin of {fmt_usd(kpis['top_colorway_margin'])}. The top-performing model-colorway combinations are concentrated among hype-driven and limited-release colorways.
            </li>
            <li>
                <strong>Channel selection creates meaningful margin differentiation.</strong>
                The spread between the highest and lowest-margin channels is {fmt_usd(channel_stats[0]['avg_profit'] - channel_stats[-1]['avg_profit'])}, meaning channel selection alone can swing a transaction from profitable to loss-making.
            </li>
            <li>
                <strong>Inventory velocity varies significantly across platforms.</strong>
                The fastest channels average ~{min(c['avg_days'] for c in channel_stats):.0f} days while the slowest reach ~{max(c['avg_days'] for c in channel_stats):.0f} days. This 2-3x spread in holding time affects capital efficiency and risk exposure.
            </li>
            <li>
                <strong>The market shows overall positive economics.</strong>
                With a {kpis['resale_premium_rate']}% premium rate and {kpis['avg_resale_to_retail']:.2f}x average resale-to-retail ratio, the Air Jordan resale market remains profitable at scale, though individual transaction outcomes vary widely (std. dev: {fmt_usd(pd_dist['std'])}).
            </li>
        </ul>
    </div>

    <div class="card">
        <h3>Strategic Recommendations</h3>
        <ul class="rec-list">
            <li>
                <strong>Prioritize Deadstock sourcing above all else.</strong>
                The {fmt_usd(ds_premium_over_used)} resale premium and {ds_data['pct_profitable'] - used_data['pct_profitable']:.0f}pp profitability advantage over Used pairs makes Deadstock the only condition tier worth sourcing at scale. VNDS is acceptable for high-demand colorways only.
            </li>
            <li>
                <strong>Focus sourcing on high-margin model-colorway combinations.</strong>
                Concentrate capital on the top-15 combinations identified in Section 2. Avoid bottom-10 combinations entirely — these consistently underperform regardless of channel or holding period.
            </li>
            <li>
                <strong>Match channel to product and urgency.</strong>
                For high-value Deadstock pairs where margin is the priority, use higher-margin channels even at the cost of longer hold times. For VNDS or time-sensitive inventory, prioritize faster-turnover platforms to reduce capital lock-up and depreciation risk.
            </li>
            <li>
                <strong>Implement seasonal timing strategies.</strong>
                Use the monthly seasonality patterns in Section 5 to time purchases (during lower-margin months) and sales (during peak-margin periods). Even small timing advantages compound across a portfolio.
            </li>
            <li>
                <strong>Monitor the margin-velocity quadrant.</strong>
                Continuously track the scatter relationship between channel margin and days-in-inventory. Optimal portfolio allocation shifts inventory toward the upper-left quadrant (high margin, fast turnover) and away from the lower-right (low margin, slow turnover).
            </li>
        </ul>
    </div>
</div>

</div><!-- container -->

<div class="footer">
    Air Jordan Sneaker Resale Market Analysis &bull; Data: 5,000 transactions ({kpis['date_range']}) &bull; Generated April 2026
</div>

<script>
Chart.defaults.font.family = "'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif";
Chart.defaults.font.size = 12;
Chart.defaults.color = '#6c757d';

const colors = {{
    accent: '#e94560',
    primary: '#1a1a2e',
    blue: '#3498db',
    green: '#27ae60',
    red: '#e74c3c',
    orange: '#f39c12',
    purple: '#9b59b6',
    teal: '#1abc9c',
    pink: '#e91e63',
    palette: ['#3498db','#e94560','#27ae60','#f39c12','#9b59b6','#1abc9c','#e91e63','#16213e','#f1c40f','#2c3e50']
}};

// Profit Histogram
new Chart(document.getElementById('profitHistChart'), {{
    type: 'bar',
    data: {{
        labels: {hist_labels},
        datasets: [{{
            label: 'Transactions',
            data: {hist_values},
            backgroundColor: {hist_labels}.map(l => parseFloat(l) < 0 ? 'rgba(231,76,60,0.7)' : 'rgba(39,174,96,0.7)'),
            borderRadius: 2
        }}]
    }},
    options: {{
        responsive: true,
        maintainAspectRatio: false,
        plugins: {{ legend: {{ display: false }} }},
        scales: {{
            x: {{ title: {{ display: true, text: 'Profit Margin (USD)' }}, grid: {{ display: false }} }},
            y: {{ title: {{ display: true, text: 'Count' }}, beginAtZero: true }}
        }}
    }}
}});

// Model Profit Chart
new Chart(document.getElementById('modelProfitChart'), {{
    type: 'bar',
    data: {{
        labels: {model_names},
        datasets: [{{
            label: 'Avg Profit ($)',
            data: {model_profits},
            backgroundColor: colors.palette,
            borderRadius: 6
        }}]
    }},
    options: {{
        responsive: true,
        maintainAspectRatio: false,
        indexAxis: 'y',
        plugins: {{ legend: {{ display: false }} }},
        scales: {{
            x: {{ title: {{ display: true, text: 'Average Profit Margin (USD)' }}, grid: {{ color: '#f0f0f0' }} }},
            y: {{ grid: {{ display: false }} }}
        }}
    }}
}});

// Colorway Profit Chart
new Chart(document.getElementById('colorwayProfitChart'), {{
    type: 'bar',
    data: {{
        labels: {cw_names},
        datasets: [{{
            label: 'Avg Profit ($)',
            data: {cw_profits},
            backgroundColor: colors.palette,
            borderRadius: 6
        }}]
    }},
    options: {{
        responsive: true,
        maintainAspectRatio: false,
        indexAxis: 'y',
        plugins: {{ legend: {{ display: false }} }},
        scales: {{
            x: {{ title: {{ display: true, text: 'Average Profit Margin (USD)' }}, grid: {{ color: '#f0f0f0' }} }},
            y: {{ grid: {{ display: false }} }}
        }}
    }}
}});

// Condition Chart
new Chart(document.getElementById('conditionChart'), {{
    type: 'bar',
    data: {{
        labels: {cond_names_chart},
        datasets: [
            {{ label: 'Avg Resale Price', data: {cond_resale_chart}, backgroundColor: 'rgba(52,152,219,0.8)', borderRadius: 6 }},
            {{ label: 'Avg Profit Margin', data: {cond_profits_chart}, backgroundColor: 'rgba(39,174,96,0.8)', borderRadius: 6 }}
        ]
    }},
    options: {{
        responsive: true,
        maintainAspectRatio: false,
        plugins: {{ legend: {{ position: 'top' }} }},
        scales: {{
            y: {{ title: {{ display: true, text: 'USD' }}, beginAtZero: true }}
        }}
    }}
}});

// Condition Metrics Chart
new Chart(document.getElementById('conditionMetricsChart'), {{
    type: 'bar',
    data: {{
        labels: {cond_names_chart},
        datasets: [
            {{ label: '% Profitable', data: {cond_pct_chart}, backgroundColor: 'rgba(39,174,96,0.8)', borderRadius: 6, yAxisID: 'y' }},
            {{ label: 'Avg Days in Inventory', data: {cond_days_chart}, backgroundColor: 'rgba(243,156,18,0.8)', borderRadius: 6, yAxisID: 'y1' }}
        ]
    }},
    options: {{
        responsive: true,
        maintainAspectRatio: false,
        plugins: {{ legend: {{ position: 'top' }} }},
        scales: {{
            y: {{ type: 'linear', position: 'left', title: {{ display: true, text: '% Profitable' }}, beginAtZero: true, max: 100 }},
            y1: {{ type: 'linear', position: 'right', title: {{ display: true, text: 'Avg Days' }}, beginAtZero: true, grid: {{ drawOnChartArea: false }} }}
        }}
    }}
}});

// Heatmap (using bar chart as approximation)
(function() {{
    const models = {heatmap_models_json};
    const conds = {heatmap_conds_json};
    const data = {heatmap_data_json};
    const datasets = conds.map((c, ci) => ({{
        label: c,
        data: models.map((m, mi) => {{
            const d = data.find(r => r.x === mi && r.y === ci);
            return d ? d.v : 0;
        }}),
        backgroundColor: ['rgba(39,174,96,0.8)','rgba(52,152,219,0.8)','rgba(231,76,60,0.8)'][ci],
        borderRadius: 4
    }}));
    new Chart(document.getElementById('heatmapChart'), {{
        type: 'bar',
        data: {{ labels: models, datasets: datasets }},
        options: {{
            responsive: true,
            maintainAspectRatio: false,
            plugins: {{ legend: {{ position: 'top' }} }},
            scales: {{
                y: {{ title: {{ display: true, text: 'Avg Profit Margin (USD)' }} }}
            }}
        }}
    }});
}})();

// Channel Scatter (Margin vs Velocity)
(function() {{
    const names = {ch_names};
    const profits = {ch_profits};
    const days = {ch_days};
    const counts = {ch_counts};
    const pts = names.map((n, i) => ({{ x: days[i], y: profits[i], label: n, r: Math.sqrt(counts[i]) / 2 }}));
    new Chart(document.getElementById('channelScatterChart'), {{
        type: 'bubble',
        data: {{
            datasets: pts.map((p, i) => ({{
                label: p.label,
                data: [{{ x: p.x, y: p.y, r: Math.max(p.r, 8) }}],
                backgroundColor: colors.palette[i] + 'CC',
                borderColor: colors.palette[i],
                borderWidth: 2
            }}))
