<script>
Chart.defaults.font.family = "'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif";
Chart.defaults.font.size = 12;
Chart.defaults.color = '#6c757d';

const colors = {{
    accent: '#e94560',
    primary: '#1a1a2e',
    blue: '#3498db',
    green: '#27ae60',
    red: '#e74c3c',
    orange: '#f39c12',
    purple: '#9b59b6',
    teal: '#1abc9c',
    pink: '#e91e63',
    palette: ['#3498db','#e94560','#27ae60','#f39c12','#9b59b6','#1abc9c','#e91e63','#16213e','#f1c40f','#2c3e50']
}};

// Profit Histogram
new Chart(document.getElementById('profitHistChart'), {{
    type: 'bar',
    data: {{
        labels: {hist_labels},
        datasets: [{{
            label: 'Transactions',
            data: {hist_values},
            backgroundColor: {hist_labels}.map(l => parseFloat(l) < 0 ? 'rgba(231,76,60,0.7)' : 'rgba(39,174,96,0.7)'),
            borderRadius: 2
        }}]
    }},
    options: {{
        responsive: true,
        maintainAspectRatio: false,
        plugins: {{ legend: {{ display: false }} }},
        scales: {{
            x: {{ title: {{ display: true, text: 'Profit Margin (USD)' }}, grid: {{ display: false }} }},
            y: {{ title: {{ display: true, text: 'Count' }}, beginAtZero: true }}
        }}
    }}
}});

// Model Profit Chart
new Chart(document.getElementById('modelProfitChart'), {{
    type: 'bar',
    data: {{
        labels: {model_names},
        datasets: [{{
            label: 'Avg Profit ($)',
            data: {model_profits},
            backgroundColor: colors.palette,
            borderRadius: 6
        }}]
    }},
    options: {{
        responsive: true,
        maintainAspectRatio: false,
        indexAxis: 'y',
        plugins: {{ legend: {{ display: false }} }},
        scales: {{
            x: {{ title: {{ display: true, text: 'Average Profit Margin (USD)' }}, grid: {{ color: '#f0f0f0' }} }},
            y: {{ grid: {{ display: false }} }}
        }}
    }}
}});

// Colorway Profit Chart
new Chart(document.getElementById('colorwayProfitChart'), {{
    type: 'bar',
    data: {{
        labels: {cw_names},
        datasets: [{{
            label: 'Avg Profit ($)',
            data: {cw_profits},
            backgroundColor: colors.palette,
            borderRadius: 6
        }}]
    }},
    options: {{
        responsive: true,
        maintainAspectRatio: false,
        indexAxis: 'y',
        plugins: {{ legend: {{ display: false }} }},
        scales: {{
            x: {{ title: {{ display: true, text: 'Average Profit Margin (USD)' }}, grid: {{ color: '#f0f0f0' }} }},
            y: {{ grid: {{ display: false }} }}
        }}
    }}
}});

// Condition Chart
new Chart(document.getElementById('conditionChart'), {{
    type: 'bar',
    data: {{
        labels: {cond_names_chart},
        datasets: [
            {{ label: 'Avg Resale Price', data: {cond_resale_chart}, backgroundColor: 'rgba(52,152,219,0.8)', borderRadius: 6 }},
            {{ label: 'Avg Profit Margin', data: {cond_profits_chart}, backgroundColor: 'rgba(39,174,96,0.8)', borderRadius: 6 }}
        ]
    }},
    options: {{
        responsive: true,
        maintainAspectRatio: false,
        plugins: {{ legend: {{ position: 'top' }} }},
        scales: {{
            y: {{ title: {{ display: true, text: 'USD' }}, beginAtZero: true }}
        }}
    }}
}});

// Condition Metrics Chart
new Chart(document.getElementById('conditionMetricsChart'), {{
    type: 'bar',
    data: {{
        labels: {cond_names_chart},
        datasets: [
            {{ label: '% Profitable', data: {cond_pct_chart}, backgroundColor: 'rgba(39,174,96,0.8)', borderRadius: 6, yAxisID: 'y' }},
            {{ label: 'Avg Days in Inventory', data: {cond_days_chart}, backgroundColor: 'rgba(243,156,18,0.8)', borderRadius: 6, yAxisID: 'y1' }}
        ]
    }},
    options: {{
        responsive: true,
        maintainAspectRatio: false,
        plugins: {{ legend: {{ position: 'top' }} }},
        scales: {{
            y: {{ type: 'linear', position: 'left', title: {{ display: true, text: '% Profitable' }}, beginAtZero: true, max: 100 }},
            y1: {{ type: 'linear', position: 'right', title: {{ display: true, text: 'Avg Days' }}, beginAtZero: true, grid: {{ drawOnChartArea: false }} }}
        }}
    }}
}});

// Heatmap (using bar chart as approximation)
(function() {{
    const models = {heatmap_models_json};
    const conds = {heatmap_conds_json};
    const data = {heatmap_data_json};
    const datasets = conds.map((c, ci) => ({{
        label: c,
        data: models.map((m, mi) => {{
            const d = data.find(r => r.x === mi && r.y === ci);
            return d ? d.v : 0;
        }}),
        backgroundColor: ['rgba(39,174,96,0.8)','rgba(52,152,219,0.8)','rgba(231,76,60,0.8)'][ci],
        borderRadius: 4
    }}));
    new Chart(document.getElementById('heatmapChart'), {{
        type: 'bar',
        data: {{ labels: models, datasets: datasets }},
        options: {{
            responsive: true,
            maintainAspectRatio: false,
            plugins: {{ legend: {{ position: 'top' }} }},
            scales: {{
                y: {{ title: {{ display: true, text: 'Avg Profit Margin (USD)' }} }}
            }}
        }}
    }});
}})();

// Channel Scatter (Margin vs Velocity)
(function() {{
    const names = {ch_names};
    const profits = {ch_profits};
    const days = {ch_days};
    const counts = {ch_counts};
    const pts = names.map((n, i) => ({{ x: days[i], y: profits[i], label: n, r: Math.sqrt(counts[i]) / 2 }}));
    new Chart(document.getElementById('channelScatterChart'), {{
        type: 'bubble',
        data: {{
            datasets: pts.map((p, i) => ({{
                label: p.label,
                data: [{{ x: p.x, y: p.y, r: Math.max(p.r, 8) }}],
                backgroundColor: colors.palette[i] + 'CC',
                borderColor: colors.palette[i],
                borderWidth: 2
            }}))
        }},
        options: {{
            responsive: true,
            maintainAspectRatio: false,
            plugins: {{ legend: {{ position: 'right', labels: {{ boxWidth: 12 }} }} }},
            scales: {{
                x: {{ title: {{ display: true, text: 'Avg Days in Inventory (lower = faster)' }} }},
                y: {{ title: {{ display: true, text: 'Avg Profit Margin (USD)' }} }}
            }}
        }}
    }});
}})();

// Channel Profitability Bar
new Chart(document.getElementById('channelPctChart'), {{
    type: 'bar',
    data: {{
        labels: {ch_names},
        datasets: [{{
            label: '% Profitable',
            data: {ch_pct},
            backgroundColor: colors.palette,
            borderRadius: 6
        }}]
    }},
    options: {{
        responsive: true,
        maintainAspectRatio: false,
        plugins: {{ legend: {{ display: false }} }},
        scales: {{
            y: {{ title: {{ display: true, text: '% of Transactions Profitable' }}, beginAtZero: true, max: 100 }}
        }}
    }}
}});

